class FileContent:
    """A downloaded file: the answer of ``get``, not yet read. Read it with :meth:`read`, :meth:`iter_bytes` or
    :meth:`save`, and close it (or use it as a context manager) when it is not read to the end.

    When the file's details are known (``get`` looked them up, or ``file=`` gave them) the SHA-256 of what was
    read is checked against theirs, and a difference raises a :class:`BackdError` with code ``checksum_mismatch``.
    """

    def __init__(self, response: httpx.Response, file: FileDetails | None = None, verify: bool = True) -> None:
        self.response = response
        #: Its details, when they were looked up.
        self.file = file
        self._verify = verify and file is not None and bool(file.get("sha256"))

    def iter_bytes(self, chunk_size: int | None = None) -> Iterator[bytes]:
        """The bytes as they arrive."""
        h = hashlib.sha256() if self._verify else None
        try:
            for chunk in self.response.iter_bytes(chunk_size):
                if h is not None:
                    h.update(chunk)
                yield chunk
        finally:
            self.response.close()
        self._check(h)

    def _check(self, h: Any) -> None:
        if h is not None and self.file is not None and h.hexdigest() != self.file["sha256"]:
            got, want = h.hexdigest()[:12], self.file["sha256"][:12]
            raise BackdError(
                f"the file read does not match its checksum (got {got}…, expected {want}…)", code="checksum_mismatch"
            )

    def read(self) -> bytes:
        """The whole file."""
        return b"".join([chunk for chunk in self.iter_bytes()])

    def text(self, encoding: str = "utf-8") -> str:
        """The whole file as text."""
        return (self.read()).decode(encoding)

    def save(self, to: str | os.PathLike[str] | BinaryIO) -> int:
        """Writes the file to a path or an open binary file, as it arrives (so a large file is not held in
        memory). Returns the bytes written. A path is written to a temporary file next to it and moved into place
        when the whole file arrived and matched its checksum."""
        n = 0
        if hasattr(to, "write"):
            for chunk in self.iter_bytes():
                cast(BinaryIO, to).write(chunk)
                n += len(chunk)
            return n
        target = Path(to)
        tmp = target.with_name(target.name + ".part")
        try:
            with tmp.open("wb") as f:
                for chunk in self.iter_bytes():
                    f.write(chunk)
                    n += len(chunk)
            tmp.replace(target)
        except BaseException:
            tmp.unlink(missing_ok=True)
            raise
        return n

    def close(self) -> None:
        self.response.close()

    def __enter__(self) -> FileContent:
        return self

    def __exit__(
        self, exc_type: type[BaseException] | None, exc: BaseException | None, tb: TracebackType | None
    ) -> None:
        self.close()


class FileVersion:
    """A made version of one file (``files(id, field).version(name)``): make it again, make it with other
    parameters, or drop it. Each waits for a worker to do it and returns the version's state."""

