    def _call(self, method: str, body: Mapping[str, Any] | None = None) -> VersionState:
        found, _ = self._files._which(self._file_id)
        path = [*self._files.path, found, "versions", self._name]
        return cast(VersionState, (self._files._client.request(method, path, body=body)).data)

    def regenerate(self) -> VersionState:
        """Again, with the parameters ``collection.yaml`` declares."""
        return self._call("POST")

    def generate(
        self,
        *,
        max_width: int | None = None,
        max_height: int | None = None,
        fit: str | None = None,
        quality: int | None = None,
        format: str | None = None,
        upscale: bool | None = None,
    ) -> VersionState:
        """With other parameters, named as in ``collection.yaml``: a box (``max_width``, ``max_height``, at least
        one), and optionally ``fit`` (``contain``, ``cover``, ``stretch``), ``quality`` (1 to 100, jpeg),
        ``format`` (``jpeg``, ``png``) and ``upscale``. Only a ``writable`` version allows it
        (``version_not_writable``)."""
        params = {
            "max_width": max_width, "max_height": max_height, "fit": fit,
            "quality": quality, "format": format, "upscale": upscale,
        }  # fmt: skip
        return self._call("POST", {k: v for k, v in params.items() if v is not None})

    def delete(self) -> VersionState:
        """Drops the copy: the version is ``pending`` again (a worker makes it) or ``empty`` (only functions make
        it)."""
        return self._call("DELETE")


